import {GameSession} from './engine.js';
import {LocalTransport} from './transport.js';
import {questions} from './questions.js';
import {tiles} from './combo.js';
const $=s=>document.querySelector(s);let transport,timer,deadline,state,selected=-1;
let pulse=()=>{};import('./field.js').then(m=>pulse=m.pulse).catch(()=>{});
function tileHtml(t){const x=tiles.find(x=>x.id===t.id);return `<div class="icon">${x.icon}</div><b>${x.name}</b><p>${x.desc}${t.topic?' · '+t.topic:''}</p>`;}
function send(a){pulse();transport.send(a);}
function boot(){clearInterval(timer);transport?.close();transport=new LocalTransport(new GameSession());transport.subscribe(render);}
function time(seconds,expire){deadline=Date.now()+seconds*1000;const tick=()=>{const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=`${left} сек`;if($('#bar'))$('#bar').style.width=left/seconds*100+'%';if(!left){clearInterval(timer);expire();}};tick();timer=setInterval(tick,200);}
function render(s){state=s;clearInterval(timer);const q=questions[s.round-1],me=s.players[0];
 $('#rounds').innerHTML=questions.map((x,i)=>`<div class="round ${i+1===s.round?'active':i+1<s.round?'done':''}"><b>${i+1<s.round?'✓':'0'+(i+1)} / ${i>5?'ФИНАЛ':'РУНД'}</b>${x.topic}</div>`).join('');
 $('#scores').innerHTML=s.players.map((p,i)=>`<div class="player"><div class="avatar ${i?'bot':''}">${i?'✧':'⌁'}</div><div class="player-name">${p.name}${i?' · компютър':''}<small>◈ ${p.credits} кредита</small></div><div class="points">${p.score}<small>ТОЧКИ</small></div></div>`).join('');
 $('#slots').innerHTML=[0,1,2].map(i=>me.tiles[i]?`<div class="slot">${tileHtml(me.tiles[i])}</div>`:`<div class="slot empty"><span>＋</span>СЛОТ 0${i+1}<p>Следващата ти възможност</p></div>`).join('');
 $('#rival').textContent=s.players[1].tiles.map(t=>tiles.find(x=>x.id===t.id).name).join(' / ')||'—  /  —  /  —';
 const stage=$('#stage'),top=label=>`<div class="stage-top"><span>РУНД ${String(s.round).padStart(2,'0')} / 08 <span style="margin:0 10px;color:#47505c">/</span> ${label}</span><span class="tag">${q.topic}</span></div>`;
 if(s.phase==='ready'){stage.innerHTML=top('ПОДГОТОВКА')+`<h2>${s.round===1?'Твоят следващ верен отговор<br>може да промени всичко.':'Нова тема. Нови възможности.'}</h2><p>${s.round===1?'Започваш с 3 кредита и празно поле. Превърни знанията си<br>в силна комбинация и изпревари NOVA.':`Предстои ${q.topic.toLowerCase()}. ${s.round>6?'Без пазар — време е комбинацията да работи.':'Отговори и спечели бюджет за следващата плочка.'}`}</p>${me.tiles.some(t=>t.id==='converter')?'<label class="convert"><input id="convert" type="checkbox"> Активирай Конвертор: 2 кредита за +1 точка при верен отговор</label>':''}<div class="actions"><button class="primary" id="start">${s.round===1?'Започни дуела':'Отвори въпроса'} →</button><span class="tag">25 СЕКУНДИ / БЕЗ БОНУС ЗА СКОРОСТ</span></div>`;$('#start').onclick=()=>send({type:'start',convert:$('#convert')?.checked});}
 if(s.phase==='quiz'){stage.innerHTML=top('ВЪПРОС')+`<h2>${q.text}</h2><div class="answers">${q.answers.map((a,i)=>`<button class="answer" data-answer="${i}"><span>${'ABCD'[i]}</span>${a}</button>`).join('')}</div><div class="actions"><span id="timer" class="timer">25 сек</span><small class="tag">ЕДИН ВЕРЕН ОТГОВОР</small></div><div class="progress"><i id="bar" style="width:100%"></i></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>send({type:'answer',answer:Number(b.dataset.answer)}));time(25,()=>send({type:'answer',answer:null}));}
 if(s.phase==='result'){const correct=s.answers[0]===q.correct;stage.innerHTML=top('РЕЗУЛТАТ')+`<h2>${correct?'Точно така. Добър ход!':s.answers[0]===null?'Времето изтече.':'Този път — не съвсем.'}</h2><p>Верният отговор: <strong style="color:white">${q.answers[q.correct]}</strong></p><div class="result-lines">${s.events[0].join('<br>')}</div><p>NOVA: ${s.answers[1]===q.correct?'верен':'грешен'} отговор · ${s.events[1].join(' · ')}</p><div class="actions"><button class="primary" id="next">${s.round<7?'Към пазара':s.round===8?'Виж финала':'Следващ рунд'} →</button></div>`;$('#next').onclick=()=>send({type:'continue'});}
 if(s.phase==='market'){selected=-1;stage.innerHTML=top('ТАЙНО НАДДАВАНЕ')+`<h2>Една плочка. Твоят ход.</h2><p>Печели най-високата оферта. При равенство — никой.</p><div class="market">${s.market.map((t,i)=>`<button data-tile="${i}" ${me.tiles.some(x=>x.id===t.id)?'disabled':''}><span class="icon">${t.icon}</span><b>${t.name}</b><small>${t.desc}</small></button>`).join('')}</div><div class="bid-controls"><label>Оферта <input id="amount" aria-label="Оферта в кредити" type="number" min="1" max="${me.credits}" value="1"></label><label>Слот <select id="slot">${[0,1,2].map(i=>`<option value="${i}">${i+1}${me.tiles[i]?' · '+tiles.find(t=>t.id===me.tiles[i].id).name:' · празен'}</option>`).join('')}</select></label><label id="focus-label" hidden>Тема <select id="focus">${[...new Set(questions.map(q=>q.topic))].map(t=>`<option>${t}</option>`).join('')}</select></label></div><div class="actions"><button class="primary" id="bid" disabled>Заключи офертата →</button><button id="skip">Пропусни</button><span id="timer" class="timer">15 сек</span></div><p id="error" role="alert"></p>`;
 document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.tile);document.querySelectorAll('[data-tile]').forEach(x=>x.classList.toggle('selected',x===b));$('#bid').disabled=false;$('#focus-label').hidden=s.market[selected].id!=='focus';pulse();});
 $('#bid').onclick=()=>{const amount=Number($('#amount').value);if(!Number.isInteger(amount)||amount<1||amount>me.credits){$('#error').textContent='Избери цяла сума между 1 и '+me.credits+'.';return;}send({type:'bid',tile:selected,amount,slot:Number($('#slot').value),topic:$('#focus').value});};$('#skip').onclick=()=>send({type:'bid'});time(15,()=>send({type:'bid'}));}
 if(s.phase==='reveal'){stage.innerHTML=top('РАЗКРИВАНЕ')+`<h2>Офертите са на масата.</h2><div class="result-lines">${s.events.join('<br>')}</div><p>Новите плочки ще се задействат от следващия рунд.</p><div class="actions"><button id="next" class="primary">Следващ рунд →</button></div>`;$('#next').onclick=()=>send({type:'continue'});}
 if(s.phase==='finished'){const delta=me.score-s.players[1].score;stage.innerHTML=top('ФИНАЛ')+`<h2>${delta>0?'Твоята комбинация спечели.':delta===0?'Споделена победа.':'Този дуел е за NOVA.'}</h2><p>Осем рунда. Осем възможности. Една машина за точки.</p><div style="font-size:56px;color:var(--lime)">${me.score} <span style="font-size:24px;color:#777">:</span> ${s.players[1].score}</div><p>Останалите кредити не участват в крайния резултат.</p><button class="primary" id="again">Още един дуел ↻</button>`;$('#again').onclick=boot;}
}
$('#rules').onclick=()=>$('#help').showModal();$('#close-help').onclick=$('#help-ok').onclick=()=>$('#help').close();$('#restart').onclick=()=>{if(state.round===1&&state.phase==='ready'||confirm('Да започнем нов мач? Текущият резултат ще се изчисти.'))boot();};
document.addEventListener('keydown',e=>{if($('#help').open||e.repeat||['INPUT','SELECT'].includes(document.activeElement.tagName))return;const i='1234'.indexOf(e.key);if(state.phase==='quiz'&&i>=0)send({type:'answer',answer:i});});boot();
